fn load(file: &str) -> HashMap<String, bool> {
    match fs::read_to_string(file) {
        Ok(s) => serde_json::from_str(&s).unwrap_or_default(),
        Err(_) => HashMap::new(),
    }
}

fn save(file: &str, todos: &HashMap<String, bool>) {
    let s = serde_json::to_string_pretty(todos).unwrap();
    fs::write(file, s).unwrap();
